import React, { useState, useEffect } from "react";
import "./Dashboard.css";

function Dashboard() {
  const [file, setFile] = useState(null);
  const [transactions, setTransactions] = useState([]);
  const [type, setType] = useState("");
  const [darkMode, setDarkMode] = useState(false);
  const [activeTab, setActiveTab] = useState("overview");
  const [loading, setLoading] = useState(false);

  // ✅ HISTORY STATE (IMPORTANT FIX)
  const [historyData, setHistoryData] = useState([]);

  useEffect(() => {
    const saved = JSON.parse(localStorage.getItem("history")) || [];
    setHistoryData(saved);
  }, []);

  const detectFromFileName = (file) => {
    if (!file) return "";
    const name = file.name.toLowerCase();
    if (name.includes("gpay")) return "GPay";
    if (name.includes("phonepe")) return "PhonePe";
    if (name.includes("paytm")) return "Paytm";
    return "";
  };

  const handleUpload = async () => {
    if (!file) return alert("Please select a PDF file");

    const formData = new FormData();
    formData.append("file", file);

    try {
      setLoading(true);

      const res = await fetch("http://localhost:8000/upload-statement/", {
        method: "POST",
        body: formData,
      });

      const data = await res.json();
      const txns = data.transactions || [];

      setTransactions(txns);

      const detectedSource =
        data.detected_type ||
        detectFromFileName(file) ||
        "Unknown";

      setType(detectedSource);

      // ✅ UPDATE HISTORY STATE + STORAGE
      const newEntry = {
        id: Date.now(),
        date: new Date().toLocaleString(),
        type: detectedSource,
        count: txns.length,
        transactions: txns
      };

      const updatedHistory = [newEntry, ...historyData];

      setHistoryData(updatedHistory);
      localStorage.setItem("history", JSON.stringify(updatedHistory));

    } catch (err) {
      console.error(err);
      alert("Error processing file");
    } finally {
      setLoading(false);
    }
  };

  const loadHistory = (item) => {
    setTransactions(item.transactions || []);
    setType(item.type || "Unknown");
    setActiveTab("overview");
  };

  // ✅ FIXED DELETE
  const deleteHistory = (id) => {
    const updated = historyData.filter((h) => h.id !== id);

    setHistoryData(updated); // 🔥 triggers UI update
    localStorage.setItem("history", JSON.stringify(updated));
  };

  return (
    <div className={`dashboard-main ${darkMode ? "dark" : ""}`}>
      <div className="container">

        {/* LOADER */}
        {loading && (
          <div style={{
            position: "fixed",
            top: 0,
            left: 0,
            width: "100%",
            height: "100%",
            background: "rgba(15, 23, 42, 0.6)",
            backdropFilter: "blur(6px)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            zIndex: 999
          }}>
            <div style={{
              background: "white",
              padding: "30px",
              borderRadius: "16px",
              textAlign: "center"
            }}>
              <h3>Analyzing Statement...</h3>
              <p>Please wait while we process your file</p>
            </div>
          </div>
        )}

        {/* NAVBAR */}
        <div className="navbar">
          <div className="logo">FinSight</div>

          <div className="nav-actions">
            <div className="tabs">
              <span
                className={`tab ${activeTab === "overview" ? "active-tab" : ""}`}
                onClick={() => setActiveTab("overview")}
              >
                Overview
              </span>

              <span
                className={`tab ${activeTab === "transactions" ? "active-tab" : ""}`}
                onClick={() => setActiveTab("transactions")}
              >
                History
              </span>
            </div>

            <div
              className={`theme-circle ${darkMode ? "dark" : "light"}`}
              onClick={() => setDarkMode(!darkMode)}
            ></div>
          </div>
        </div>

        {/* HERO */}
        <div className="hero">
          <h1>Personal Expense Intelligence</h1>
          <p>AI-powered financial insights from your statements</p>
        </div>

        {/* KPI */}
        {activeTab === "overview" && (
          <div className="kpi-grid">
            <div className="kpi-card">
              <h4>Statement Source</h4>
              <p>{type || "Not uploaded"}</p>
            </div>

            <div className="kpi-card">
              <h4>Total Transactions</h4>
              <p>{transactions.length}</p>
            </div>

            <div className="kpi-card">
              <h4>Status</h4>
              <p>{transactions.length ? "Processed" : "Waiting"}</p>
            </div>
          </div>
        )}

        {/* OVERVIEW */}
        {activeTab === "overview" && (
          <>
            <div className="top-section">
              <div className="card upload-card">
                <h3>Upload Statement</h3>

                <div className="upload-row">
                  <input
                    type="file"
                    accept=".pdf"
                    onChange={(e) => setFile(e.target.files[0])}
                  />
                  <button onClick={handleUpload}>
                    Analyze Statement
                  </button>
                </div>
              </div>

              <div className="card summary-card">
                <h3>Insights Summary</h3>
                <p>Smart categorization & insights powered by AI.</p>
              </div>
            </div>

            {transactions.length > 0 && (
              <div className="card table-card">
                <h3>Transaction Ledger</h3>

                <div className="table-wrapper">
                  <table>
                    <thead>
                      <tr>
                        <th>Date</th>
                        <th>Type</th>
                        <th>Description</th>
                        <th>Amount</th>
                        <th>Category</th>
                        <th>Need/Want</th>
                      </tr>
                    </thead>

                    <tbody>
                      {transactions.map((txn, i) => (
                        <tr key={i}>
                          <td>{txn.date || "-"}</td>
                          <td className={txn.type === "debit" ? "debit" : "credit"}>
                            {txn.type}
                          </td>
                          <td>{txn.description}</td>
                          <td>₹{txn.amount}</td>
                          <td>{txn.category || "Other"}</td>
                          <td>{txn.classification || "Other"}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            )}
          </>
        )}

        {/* HISTORY */}
        {activeTab === "transactions" && (
          <div style={{ marginTop: "30px" }}>
            <h2 style={{ marginBottom: "20px" }}>Upload History</h2>

            {historyData.map((h) => (
              <div
                key={h.id}
                style={{
                  background: "rgba(255,255,255,0.6)",
                  padding: "20px",
                  borderRadius: "16px",
                  marginBottom: "15px",
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "center"
                }}
              >
                <div>
                  <div style={{ fontWeight: "600" }}>{h.type}</div>
                  <div style={{ fontSize: "13px", color: "#64748b" }}>
                    {h.date}
                  </div>
                </div>

                <div style={{ display: "flex", gap: "12px" }}>
                  <button onClick={() => loadHistory(h)}>
                    View
                  </button>

                  <button
                    onClick={() => deleteHistory(h.id)}
                    style={{
                      background: "linear-gradient(135deg, #e63946, #b71c1c)"
                    }}
                  >
                    Delete
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}

      </div>
    </div>
  );
}

export default Dashboard;
